namespace hello::daw {

    namespace {

        std::filesystem::path pluginsOf(const std::filesystem::path &utauDirectory) {
            return utauDirectory.empty() ? std::filesystem::path() : utauDirectory / u"plugins";
        }

    }

    QList<std::filesystem::path>
        ClassicPluginContribution::pluginFolders(const AppSettings &settings) {
        // In the order of the voice bank folders of VoiceBankSettings::locations()
        QList<std::filesystem::path> folders{userDirectory(settings)};
        if (const auto data = UtauSettings::dataDirectory(); !data.empty()) {
            folders.push_back(data / u"plugins");
        }
        if (const auto utauPlugins = pluginsOf(settings.utau().directory()); !utauPlugins.empty()) {
            folders.push_back(utauPlugins);
        }
        return folders;
    }

    void ClassicPluginContribution::openFolder(QWidget *parent, const AppSettings &settings,
                                               const std::filesystem::path &folder) {
        const auto text = QString::fromStdU16String(folder.u16string());
        const auto shown = QDir::toNativeSeparators(text);
        const auto warn = [parent](const QString &message) {
            QMessageBox::warning(parent, tr("Open Plugin Folder"), message);
        };
        // The creation fails with EPERM in the Documents folder that macOS denies until the user
        // allows the access.
        std::error_code error;
        if (folder == userDirectory(settings) &&
            !std::filesystem::create_directories(folder, error) && error) {
            warn(tr("The folder \"%1\" cannot be created: %2")
                     .arg(shown, kit::FolderAccess::reasonOf(error)));
            return;
        }
        // is_directory() reports no error for a missing folder.
        if (!std::filesystem::is_directory(folder, error)) {
            warn(error ? tr("The folder \"%1\" cannot be opened: %2")
                             .arg(shown, kit::FolderAccess::reasonOf(error))
                       : tr("The folder \"%1\" does not exist.").arg(shown));
            return;
        }
        QDesktopServices::openUrl(QUrl::fromLocalFile(text));
    }

    ClassicPluginContribution::ClassicPluginContribution() = default;

    ClassicPluginContribution::~ClassicPluginContribution() = default;

    // The plugins of UTAU edit the notes of a project, so the commands are in the project window
    // alone.
    const QAK::ActionExtension *
        ClassicPluginContribution::extension(const QString &windowKind) const {
        return windowKind == QLatin1String(Editor::projectWindowName) ? classicPluginActions()
                                                                      : nullptr;
    }

    void ClassicPluginContribution::addActions(QWidget *widget, QAK::WidgetActionContext *context) {
        const auto window = qobject_cast<ProjectWindow *>(widget);
        if (!window) {
            return;
        }
        // An action that is not triggerable. This plugin fills its menu each time the menu opens.
        const auto menu = new QMenu(window);
        menu->setToolTipsVisible(true);
        QObject::connect(menu, &QMenu::aboutToShow, menu,
                         [this, menu, window] { fill(menu, window); });
        // Converted from UTF-8 rather than a literal, whose data would be unloaded with this
        // library
        context->addAction(QString::fromUtf8("helloutau.tools.classicPlugins"), menu->menuAction());

        // The menu at the mouse pointer. The action is in no menu, so the window holds it for its
        // shortcut to take effect.
        const auto atPointer = new QAction(window);
        window->addAction(atPointer);
        const QPointer<QMenu> guarded(menu);
        QObject::connect(atPointer, &QAction::triggered, window, [guarded] {
            if (guarded) {
                guarded->popup(QCursor::pos());
            }
        });
        context->addAction(QString::fromUtf8("helloutau.tools.classicPluginsAtPointer"), atPointer);
    }

    std::filesystem::path ClassicPluginContribution::userDirectory(const AppSettings &settings) {
        return settings.classicExtensionsDirectory() / u"plugins";
    }

    void ClassicPluginContribution::fill(QMenu *menu, ProjectWindow *window) {
        if (m_utauDirectory != window->editor()->settings().utau().directory()) {
            refresh(window);
        }

        menu->clear();
        for (const auto &plugin : std::as_const(m_plugins)) {
            // The name is plain text. An ampersand in it is not a mnemonic.
            auto name = plugin.name;
            const auto action =
                menu->addAction(name.replace(QLatin1Char('&'), QLatin1String("&&")));
            action->setEnabled(plugin.isAvailable());
            action->setToolTip(plugin.unavailableReason);
            QObject::connect(action, &QAction::triggered, window,
                             [window, plugin] { runClassicPlugin(window, plugin); });
        }
        if (m_plugins.isEmpty()) {
            menu->addAction(tr("No Plugins"))->setEnabled(false);
        }

        // A folder or a plugin that cannot be read, such as a folder in the Documents folder that
        // macOS keeps from the application, is reported on request, because a message box
        // would appear each time the menu opens.
        if (!m_diagnostics.isEmpty()) {
            QObject::connect(menu->addAction(tr("Some Plugins Cannot Be Read...")),
                             &QAction::triggered, window, [window, diagnostics = m_diagnostics] {
                                 DiagnosticBox::report(window, tr("Classic Plugins"), diagnostics);
                             });
        }

        menu->addSeparator();
        QObject::connect(menu->addAction(tr("&Refresh")), &QAction::triggered, window,
                         [this, window] { refresh(window); });
        const auto &settings = window->editor()->settings();
        QObject::connect(menu->addAction(tr("&Open Plugin Folder")), &QAction::triggered, window,
                         [window, folder = userDirectory(settings)] {
                             openFolder(window, window->editor()->settings(), folder);
                         });
        const auto utauPlugins = pluginsOf(settings.utau().directory());
        if (!utauPlugins.empty()) {
            QObject::connect(menu->addAction(tr("Open &UTAU Plugin Folder")), &QAction::triggered,
                             window, [window, utauPlugins] {
                                 openFolder(window, window->editor()->settings(), utauPlugins);
                             });
        }
    }

    void ClassicPluginContribution::refresh(ProjectWindow *window) {
        const auto &settings = window->editor()->settings();
        // A folder that does not exist yields no plugins, and a folder whose plugin.txt cannot
        // be read is left out of the menu, as in UTAU. The menu offers the reasons.
        m_diagnostics.clear();
        m_plugins = ClassicPlugin::discover(pluginFolders(settings), m_diagnostics);
        m_utauDirectory = settings.utau().directory();
    }

}
